using Microsoft.AspNetCore.Mvc;using GameVault.Services;using GameVault.Models;using GameVault.ViewModels;
namespace GameVault.Controllers;
public class GamesController(GameVaultStore store):Controller { private string? Email=>HttpContext.Session.GetString("Email");private IActionResult SignIn()=>RedirectToAction("Login","Account",new{returnUrl=Url.Action("Create","Games")});public IActionResult Create(){if(Email==null)return SignIn();return View(new GameFormViewModel());} [HttpPost,ValidateAntiForgeryToken] public IActionResult Create(GameFormViewModel m){if(Email==null)return SignIn();if(!ModelState.IsValid)return View(m);store.Add(Map(m),Email!);TempData["Toast"]="Game added to your mission log.";return RedirectToAction("Index","Home");} public IActionResult Edit(int id){if(Email==null)return SignIn();var g=store.Find(id,Email);if(g==null||g.OwnerEmail!=Email)return NotFound();return View(new GameFormViewModel{Id=g.Id,Title=g.Title,Genre=g.Genre,Platform=g.Platform,Status=g.Status,Rating=g.Rating,HoursPlayed=g.HoursPlayed,Notes=g.Notes,CoverUrl=g.CoverUrl});} [HttpPost,ValidateAntiForgeryToken] public IActionResult Edit(GameFormViewModel m){if(Email==null)return SignIn();if(!ModelState.IsValid)return View(m);if(!store.Update(Map(m),Email!))return NotFound();TempData["Toast"]="Mission log updated.";return RedirectToAction("Index","Home");} [HttpPost,ValidateAntiForgeryToken] public IActionResult Delete(int id){if(Email==null)return SignIn();store.Delete(id,Email!);TempData["Toast"]="Game removed from your log.";return RedirectToAction("Index","Home");} private static Game Map(GameFormViewModel m)=>new(){Id=m.Id,Title=m.Title.Trim(),Genre=m.Genre,Platform=m.Platform,Status=m.Status,Rating=m.Rating,HoursPlayed=m.HoursPlayed,Notes=m.Notes,CoverUrl=string.IsNullOrWhiteSpace(m.CoverUrl)?"https://images.unsplash.com/photo-1542751371-adc38448a05e?auto=format&fit=crop&w=900&q=80":m.CoverUrl}; }
